:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: dark;

  --text-color: rgba(255, 255, 255, 0.87);
  --bg-color: #121212;
  --app-bg: radial-gradient(circle at center, #1a1a2e 0%, #0f0f1a 100%);
  --controls-bg: rgba(20, 20, 35, 0.8);
  --border-color: rgba(255, 255, 255, 0.1);
  --primary-color: #3b82f6;
  --primary-gradient: linear-gradient(135deg, #3b82f6, #2563eb);
  --primary-gradient-hover: linear-gradient(135deg, #2563eb, #1d4ed8);
  --title-gradient: linear-gradient(135deg, #6ee7b7, #3b82f6);
  --range-bg: rgba(255, 255, 255, 0.15);
  --shadow-color: rgba(0, 0, 0, 0.5);

  color: var(--text-color);
  background-color: var(--bg-color);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
  overflow: hidden;
}

#root {
  width: 100vw;
  height: 100vh;
}

.app-container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--app-bg);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  padding: 16px 24px;
  background: var(--controls-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  box-shadow: 0 10px 30px var(--shadow-color);
  max-width: 90vw;
  justify-content: center;
  align-items: center;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 120px;
}

.title {
  position: absolute;
  top: 24px;
  left: 32px;
  z-index: 10;
  font-size: 1.5rem;
  font-weight: 700;
  background: var(--title-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 10px rgba(0,0,0,0.3);
  pointer-events: none;
}

.label {
  font-size: 0.75rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.7);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  justify-content: space-between;
}

.btn {
  background: var(--primary-gradient);
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
}

.btn:hover {
  background: var(--primary-gradient-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(59, 130, 246, 0.4);
}

.btn:active {
  transform: translateY(1px);
}

.color-picker {
  -webkit-appearance: none;
  appearance: none;
  border: none;
  width: 100%;
  height: 32px;
  border-radius: 6px;
  cursor: pointer;
  background: transparent;
}

.color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.color-picker::-webkit-color-swatch {
  border: 1px solid var(--border-color);
  border-radius: 6px;
}

.color-picker::-moz-color-swatch {
  border: 1px solid var(--border-color);
  border-radius: 6px;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--range-bg);
  border-radius: 3px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(59, 130, 246, 0.6);
  transition: transform 0.1s;
}

input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

input[type="range"]::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(59, 130, 246, 0.6);
  transition: transform 0.1s;
}

input[type="range"]::-moz-range-thumb:hover {
  transform: scale(1.2);
}

@media (max-width: 768px) {
  .controls {
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    width: 92vw;
    padding: 12px 14px;
    gap: 10px;
    border-radius: 14px;
  }

  .control-group {
    min-width: calc(50% - 8px);
    flex: 1 1 calc(50% - 8px);
  }

  .title {
    top: 16px;
    left: 16px;
    font-size: 1.15rem;
  }
}

import { useEffect, useRef, useState } from 'react'

interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  size: number
  color: string
  alpha: number
  life: number
  maxLife: number
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)

  // コントロールの状態
  const [particleColor, setParticleColor] = useState<string>('#3b82f6')
  const [particleCount, setParticleCount] = useState<number>(50)
  const [speed, setSpeed] = useState<number>(2)
  const [isPaused, setIsPaused] = useState<boolean>(false)

  // マウス/タッチ座標（初期からactiveをtrueにしてロード直後から動くようにする）
  const mouseRef = useRef({ 
    x: typeof window !== 'undefined' ? window.innerWidth / 2 : 0, 
    y: typeof window !== 'undefined' ? window.innerHeight / 2 : 0, 
    active: true 
  })

  // パフォーマンス向上のためパーティクル配列や最新の設定値をrefで管理
  const particlesRef = useRef<Particle[]>([])
  const paramsRef = useRef({ particleColor, particleCount, speed, isPaused })

  useEffect(() => {
    paramsRef.current = { particleColor, particleCount, speed, isPaused }
  }, [particleColor, particleCount, speed, isPaused])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    let animationFrameId: number
    let width = (canvas.width = window.innerWidth)
    let height = (canvas.height = window.innerHeight)

    const handleResize = () => {
      if (!canvas) return
      width = canvas.width = window.innerWidth
      height = canvas.height = window.innerHeight
    }

    window.addEventListener('resize', handleResize)

    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current.x = e.clientX
      mouseRef.current.y = e.clientY
      mouseRef.current.active = true
    }

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouseRef.current.x = e.touches[0].clientX
        mouseRef.current.y = e.touches[0].clientY
        mouseRef.current.active = true
      }
    }

    const handleMouseLeave = () => {
      mouseRef.current.active = false
    }

    window.addEventListener('mousemove', handleMouseMove)
    window.addEventListener('touchmove', handleTouchMove)
    window.addEventListener('touchstart', handleTouchMove)
    document.addEventListener('mouseleave', handleMouseLeave)

    const createParticle = (x: number, y: number): Particle => {
      const angle = Math.random() * Math.PI * 2
      const spd = (Math.random() * 2 + 1) * paramsRef.current.speed
      return {
        x,
        y,
        vx: Math.cos(angle) * spd,
        vy: Math.sin(angle) * spd,
        size: Math.random() * 4 + 2,
        color: paramsRef.current.particleColor,
        alpha: 1,
        life: 0,
        maxLife: Math.random() * 60 + 40,
      }
    }

    const render = () => {
      ctx.fillStyle = 'rgba(18, 18, 26, 0.2)'
      ctx.fillRect(0, 0, width, height)

      const { particleCount, isPaused, particleColor } = paramsRef.current

      if (!isPaused) {
        // マウス位置に向かって、または周囲にパーティクルを生成
        if (mouseRef.current.active) {
          for (let i = 0; i < Math.floor(particleCount / 10) + 1; i++) {
            particlesRef.current.push(createParticle(mouseRef.current.x, mouseRef.current.y))
          }
        }
      }

      const particles = particlesRef.current

      // パーティクルの更新と描画
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i]
        p.x += p.vx
        p.y += p.vy
        p.life++
        p.alpha = 1 - p.life / p.maxLife

        if (p.life >= p.maxLife || p.alpha <= 0) {
          particles.splice(i, 1)
          continue
        }

        ctx.save()
        ctx.globalAlpha = Math.max(0, p.alpha)
        ctx.fillStyle = p.color
        ctx.beginPath()
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2)
        ctx.shadowBlur = 10
        ctx.shadowColor = p.color
        ctx.fill()
        ctx.restore()
      }

      // パーティクル同士のライン描画（負荷軽減のため最大数を制限）
      ctx.strokeStyle = particleColor
      ctx.lineWidth = 0.5
      const maxLimit = Math.min(particles.length, 80)
      for (let i = 0; i < maxLimit; i++) {
        for (let j = i + 1; j < maxLimit; j++) {
          const dx = particles[i].x - particles[j].x
          const dy = particles[i].y - particles[j].y
          const dist = Math.sqrt(dx * dx + dy * dy)
          if (dist < 60) {
            ctx.save()
            ctx.globalAlpha = (1 - dist / 60) * 0.2 * particles[i].alpha
            ctx.beginPath()
            ctx.moveTo(particles[i].x, particles[i].y)
            ctx.lineTo(particles[j].x, particles[j].y)
            ctx.stroke()
            ctx.restore()
          }
        }
      }

      animationFrameId = requestAnimationFrame(render)
    }

    render()

    return () => {
      window.removeEventListener('resize', handleResize)
      window.removeEventListener('mousemove', handleMouseMove)
      window.removeEventListener('touchmove', handleTouchMove)
      window.removeEventListener('touchstart', handleTouchMove)
      document.removeEventListener('mouseleave', handleMouseLeave)
      cancelAnimationFrame(animationFrameId)
    }
  }, [])

  return (
    <div className="app-container">
      <h1 className="title">パーティクルアニメーション</h1>

      <div className="canvas-container">
        <canvas ref={canvasRef} />
      </div>

      <div className="controls">
        <div className="control-group">
          <label className="label">
            <span>カラー</span>
          </label>
          <input
            type="color"
            className="color-picker"
            value={particleColor}
            onChange={(e) => setParticleColor(e.target.value)}
          />
        </div>

        <div className="control-group">
          <label className="label">
            <span>密度</span>
            <span>{particleCount}</span>
          </label>
          <input
            type="range"
            min="10"
            max="150"
            value={particleCount}
            onChange={(e) => setParticleCount(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label className="label">
            <span>速度</span>
            <span>{speed.toFixed(1)}</span>
          </label>
          <input
            type="range"
            min="0.5"
            max="5"
            step="0.1"
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
          />
        </div>

        <div className="control-group" style={{ minWidth: 'auto' }}>
          <label className="label">&nbsp;</label>
          <button className="btn" onClick={() => setIsPaused(!isPaused)}>
            {isPaused ? '再開' : '一時停止'}
          </button>
        </div>
      </div>
    </div>
  )
}
